130	std::complex<double> Lsm1_2me(double s, double t, double m1sq, double m3sq) {
131	  std::complex<double> Li2[4];
132	  double arg[4], omarg[4], f2me;
133	  std::complex<double> wlog[4];
134	
135	  // htheta(s) lambda function: half + half * sign(1, s)
136	  auto htheta = [](double val) -> double { return half + half * sign(val); };
137	
138	  // f2me = (s + t - m1sq - m3sq) / (s * t - m1sq * m3sq)
139	  f2me = (s + t - m1sq - m3sq) / (s * t - m1sq * m3sq);
140	
141	  // arg and omarg initialization
142	  arg[0] = f2me * s;
143	  arg[1] = f2me * t;
144	  arg[2] = f2me * m1sq;
145	  arg[3] = f2me * m3sq;
146	
147	  for (int j = 0; j < 4; j++) {
148	    omarg[j] = one - arg[j];
149	
150	    // wlog(j) = log(abs(arg(j))) + impi * cplx1(htheta(-arg(j)) * sign(1,
151	    // f2me))
152	    wlog[j] = std::log(std::abs(arg[j])) +
153	              impi * cplx1(htheta(-arg[j]) * std::copysign(1.0, f2me));
154	
155	    if (omarg[j] > one) {
156	      // Li2(j) = cplx1(pisqo6 - ddilog(arg(j))) - wlog(j) *
157	      // cplx1(log(omarg(j)))
158	      Li2[j] =
159	          cplx1(pisqo6 - ddilog(arg[j])) - wlog[j] * cplx1(std::log(omarg[j]));
160	    } else {
161	      // Li2(j) = cplx1(ddilog(omarg(j)))
162	      Li2[j] = cplx1(ddilog(omarg[j]));
163	    }
164	  }
165	
166	  // Final result: Lsm1_2me = Li2(1) + Li2(2) - Li2(3) - Li2(4)
167	  return Li2[0] + Li2[1] - Li2[2] - Li2[3];
168	}
